    say(R.houMid, "HOUSE", 6, 0.62);
    say(R.base + 7, "PERFUME", 5.4, 0.62);
    [2010, 2014, 2018, 2022, 2026].forEach((y) => say(yearR(y) - 3, String(y), 5.2, 0.42));
    say(R.und - 3, "NO YEAR FOUND", 4.6, 0.42);
    say(R.frame0 - 9, "THE EARTH", 5.4, 0.42);
